th.we,td.we{background:var(--weekend)}
th.td,td.td{background:var(--today)}
thead th.we{background:var(--soft)}
thead th.td{background:var(--today);color:var(--ink)}
td.dcol{background:var(--surface)}
.dcol b{display:block;font-size:15px}
th.dt b{display:block;font-size:13px;color:var(--ink);letter-spacing:0;text-transform:none}
.ev{margin-bottom:3px}
.ev b{font-family:var(--mono);font-size:11px;padding:1px 5px;border-radius:4px;margin-right:5px}
.ev.out b{background:var(--soft);color:var(--muted)}
.ev.in b{background:var(--accent);color:var(--accent-ink)}
.party{font-family:var(--mono);font-size:12px;color:var(--muted)}
button.cl{display:block;width:100%;text-align:left;font:inherit;margin:4px 0;padding:4px 8px;border-radius:6px;border:0;font-weight:600;font-size:12.5px;cursor:pointer}
button.cl.ok{background:var(--ok-bg);color:var(--ok)}
button.cl.gap{background:var(--bad-bg);color:var(--bad)}
button.cl small{display:block;font-weight:400;opacity:.9}
.cedit{display:grid;gap:6px;margin:4px 0;padding:8px;border:1px solid var(--accent);border-radius:8px;background:var(--surface)}
.stay{color:var(--muted)}
.vac{color:var(--line)}
table.cal{font-size:14px;line-height:1.4}
table.cal th,table.cal td{font-size:14px;padding:10px 12px;font-family:var(--sans)}
table.cal th.dt,table.cal td.dt{min-width:132px;width:132px}
table.cal thead th{text-transform:none;letter-spacing:0;font-weight:600;color:var(--muted);white-space:nowrap}
table.cal thead th.td{color:var(--ink)}
table.cal .dcol{font-family:var(--sans);font-size:14px;font-weight:700;width:64px;min-width:64px;color:var(--ink)}
table.cal td.sb{background:color-mix(in srgb,var(--accent-soft) 40%,var(--surface));border-left:4px solid var(--accent)}
table.cal td.sb.cont{border-left-style:dashed}
table.cal td.sb.checkedin{border-left-color:var(--ok)}
table.cal .vac{color:var(--muted);opacity:.45}
.g-name{font-weight:700;color:var(--ink)}
.g-sub{color:var(--muted)}
.g-row{display:flex;flex-wrap:wrap;gap:4px 12px;margin:4px 0 2px}
.g-arr{font:inherit;padding:0;border:0;background:none;text-decoration:none;cursor:pointer}
.g-clean{display:block;width:100%;text-align:left;font:inherit;font-size:13px;margin-top:4px;padding:3px 6px;border-radius:6px;border:0;cursor:pointer;background:transparent}
.g-clean.ok{background:var(--ok-bg)}
.g-clean.gap{background:var(--bad-bg)}
.list{display:grid;gap:8px;padding:0;margin:0;list-style:none}
.item{background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:10px 14px;display:flex;gap:10px;justify-content:space-between;align-items:flex-start}
.item.bad{border-left:4px solid var(--bad)}
.item.warn{border-left:4px solid var(--warn)}
.item .x{flex:none;font:inherit;border:0;background:none;color:var(--muted);cursor:pointer;font-size:18px;line-height:1;padding:2px 6px}
.addrow{display:grid;grid-template-columns:1fr auto;gap:8px;margin-top:10px}
.two{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:20px}
.toast{position:fixed;left:50%;transform:translateX(-50%);bottom:calc(20px + env(safe-area-inset-bottom,0px));background:var(--ink);color:var(--bg);padding:9px 16px;border-radius:8px;font-size:13px;z-index:40}
@media (prefers-reduced-motion:no-preference){.bar i{transition:width .25s}}
@media (max-width:560px){.detail{padding-left:14px}.grid2{grid-template-columns:1fr}}
details.done-list>summary{color:var(--muted);font-size:13px;padding:10px 0 4px;cursor:pointer;list-style:none;display:flex;align-items:center;gap:6px}
details.done-list>summary::-webkit-details-marker{display:none}
details.done-list>summary::before{content:"▶";font-size:10px;display:inline-block;transition:transform .15s}
details.done-list[open]>summary::before{transform:rotate(90deg)}
</style>

<div class="wrap">
  <header><h1>Daily Dashboard</h1></header>
  <nav aria-label="Jump to a section">
    <button data-jump="cal">Calendar</button>
    <button data-jump="tasks">Today<span class="count" id="c-today"></span></button>
    <button data-jump="wait">Waiting and flags<span class="count" id="c-wait"></span></button>
    <button data-jump="notes">Notes</button>
  </nav>
  <div class="status" id="status" role="status">Connecting to the board database</div>
  <main id="view"></main>
</div>
<div class="toast" id="toast" hidden></div>
<datalist id="cleaners"><option value="北村"><option value="石戸"><option value="野村"><option value="Genelyn"></datalist>

<script>
(function(){
  var S={tasks:[],stays:[],cleans:[],board:null,inbox:null,playbook:null,pbOpen:{},open:{},tab:'today',db:null,edit:null,stale:false,confirm:null,
    loaded:{tasks:false,stays:false,cleans:false,board:false}};
  var $=function(id){return document.getElementById(id)};
  function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
  function todayJST(){return new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Tokyo'})}
  function addDays(iso,n){var d=new Date(iso+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}
  function fmt(iso){return new Date(iso+'T00:00:00Z').toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short',timeZone:'UTC'}).replace(',','')}
  function dow(iso){return new Date(iso+'T00:00:00Z').getUTCDay()}
  function toast(m){var t=$('toast');t.textContent=m;t.hidden=false;clearTimeout(toast._t);toast._t=setTimeout(function(){t.hidden=true},3200)}
  function setStatus(m,err){var s=$('status');s.textContent=m;s.className='status'+(err?' err':'')}
  function hhmm(){return new Date().toLocaleTimeString('en-GB',{timeZone:'Asia/Tokyo',hour:'2-digit',minute:'2-digit'})}
  function write(p){
    if(!S.db){setStatus('Not saved: the board database is not connected in this view. Open the board in the Claude app.',true);toast('Not saved');return Promise.resolve(false)}
    return p().then(function(){setStatus('Saved '+hhmm());return true},function(e){setStatus('Save failed ('+((e&&e.code)||'error')+'): '+((e&&e.message)||''),true);toast('Not saved');return false});
  }
  function byId(list,id){return list.filter(function(x){return x._id===id})[0]}
  function now(){return new Date().toISOString()}

  /* ---------- Today ---------- */
  function taskForm(t){
    var isNew=!t, d=t||{title:'',prio:'later',deadline:'',next:'',why:'',drafts:[]};
    var h='<div class="form" data-form="task" data-id="'+esc(isNew?'new':t._id)+'">';
    h+='<label>Task<input type="text" data-f="title" value="'+esc(d.title)+'"></label>';
    h+='<div class="grid2"><label>Priority<select data-f="prio"><option value="must"'+(d.prio==='must'?' selected':'')+'>Must do today</option><option value="later"'+(d.prio!=='must'?' selected':'')+'>If there is time</option></select></label>';
    h+='<label>Deadline<input type="text" data-f="deadline" value="'+esc(d.deadline||'')+'"></label></div>';
    h+='<label>Next action<input type="text" data-f="next" value="'+esc(d.next||'')+'"></label>';
    h+='<label>Context<textarea data-f="why">'+esc(d.why||'')+'</textarea></label>';
    (d.drafts||[]).forEach(function(x){h+=draftForm(x)});
    h+='<div class="btns"><button class="btn small" data-act="add-draft">Add a draft</button></div>';
    h+='<div class="btns"><button class="btn pri" data-act="save-task">Save</button><button class="btn" data-act="cancel">Cancel</button>';
    if(!isNew){ h+= S.confirm===t._id?'<button class="btn danger" data-act="del-task" data-id="'+esc(t._id)+'">Really delete this task</button>':'<button class="btn danger" data-act="ask-del" data-id="'+esc(t._id)+'">Delete</button>' }
    return h+'</div></div>';
  }
  function draftForm(x){
    x=x||{label:'',lang:'ja',text:'',en:''};
    return '<div class="dedit" data-draft="1"><label>Draft title<input type="text" data-d="label" value="'+esc(x.label)+'"></label>'+
      '<label>Language<select data-d="lang"><option value="ja"'+(x.lang==='ja'?' selected':'')+'>Japanese</option><option value="en"'+(x.lang!=='ja'?' selected':'')+'>English</option></select></label>'+
      '<label>Text<textarea data-d="text">'+esc(x.text)+'</textarea></label>'+
      '<label>English translation (optional)<textarea data-d="en">'+esc(x.en||'')+'</textarea></label>'+
      '<div class="btns"><button class="btn small danger" data-act="rm-draft">Remove this draft</button></div></div>';
  }
  function renderToday(){
    var tasks=S.tasks.slice().sort(function(a,b){return (a.order||0)-(b.order||0)});
    var h='<div class="topline"><div class="progress">';
    if(tasks.length){var dn=tasks.filter(function(t){return t.done}).length;h+='<span>'+dn+' of '+tasks.length+' done</span><span class="bar"><i style="width:'+Math.round(dn/tasks.length*100)+'%"></i></span>'}
    h+='</div><button class="btn pri" data-act="new-task">Add task</button></div>';
    if(S.edit&&S.edit.type==='task'&&S.edit.id==='new') h+='<div class="task open">'+taskForm(null)+'</div>';
    if(!tasks.length) return h+'<div class="empty">'+(S.loaded.tasks?'No tasks yet. Add one, or ask Claude to refresh the board.':'Loading tasks')+'</div>';
    var open=tasks.filter(function(t){return !t.done});
    var must=open.filter(function(t){return t.prio==='must'}), later=open.filter(function(t){return t.prio!=='must'});
    function group(label,list){return list.length?'<h2>'+label+'</h2>'+list.map(card).join(''):''}
    h+=group('Must do today',must)+group('If there is time',later);
    var done=tasks.filter(function(t){return t.done});
    if(done.length) h+='<details class="done-list"><summary>Done ('+done.length+')</summary>'+done.map(card).join('')+'</details>';
    return h;
  }
  function card(t){
    var editing=S.edit&&S.edit.type==='task'&&S.edit.id===t._id, isOpen=editing||!!S.open[t._id];
    var h='<div class="task'+(isOpen?' open':'')+(t.done?' done':'')+'" data-id="'+esc(t._id)+'"><div class="row">';
    h+='<button class="check" data-act="done" data-id="'+esc(t._id)+'" aria-pressed="'+(!!t.done)+'" aria-label="Mark done: '+esc(t.title)+'">'+(t.done?'&#10003;':'')+'</button>';
    h+='<button class="head" data-act="open" data-id="'+esc(t._id)+'" aria-expanded="'+isOpen+'"><div class="title">'+esc(t.title)+'</div><div class="meta">';
    if(t.deadline) h+='<span class="chip due">'+esc(t.deadline)+'</span>';
    if(t.source) h+='<span class="chip">'+esc(t.source)+'</span>';
    if(t.carried) h+='<span class="chip bad">carried over x'+esc(t.carried)+'</span>';
    if(t.drafts&&t.drafts.length) h+='<span class="chip ok">'+t.drafts.length+' draft'+(t.drafts.length>1?'s':'')+' ready</span>';
    h+='</div></button></div>';
    if(editing) h+=taskForm(t);
    else if(isOpen){
      h+='<div class="detail">';
      if(t.next) h+='<div><div class="lbl">Next action</div><div class="next">'+esc(t.next)+'</div></div>';
      if(t.why) h+='<div><div class="lbl">Context</div><div>'+esc(t.why)+'</div></div>';
      (t.drafts||[]).forEach(function(d,i){
        h+='<div class="draft"><div class="draft-h"><span>'+esc(d.label)+'</span><button class="copy" data-act="copy" data-id="'+esc(t._id)+'" data-i="'+i+'">Copy</button></div>';
        h+='<pre lang="'+(d.lang||'en')+'">'+esc(d.text)+'</pre>';
        if(d.en) h+='<details><summary>English translation</summary><pre>'+esc(d.en)+'</pre></details>';
        h+='</div>';
      });
      h+='<div class="btns"><button class="btn pri" data-act="done" data-id="'+esc(t._id)+'">'+(t.done?'Mark not done':'Mark done')+'</button><button class="btn" data-act="edit-task" data-id="'+esc(t._id)+'">Edit</button></div></div>';
    }
    return h+'</div>';
  }

  /* ---------- Calendar ---------- */
  function staysFor(u){return S.stays.filter(function(s){return (s.units||[]).indexOf(u)>-1})}
  function cleanOn(u,d){return S.cleans.filter(function(c){return c.unit===u&&c.date===d})}
  function assigned(u,d){return cleanOn(u,d).filter(function(c){return c.cleaner})}
  function cleanEditor(u,d,cur){
    return '<div class="cedit" data-form="clean" data-date="'+d+'" data-unit="'+u+'"><label class="lbl">Who cleans '+u+' on '+esc(fmt(d))+'</label>'+
      '<input type="text" list="cleaners" data-f="cleaner" placeholder="Name" value="'+esc(cur?cur.cleaner:'')+'">'+
      '<input type="text" data-f="note" placeholder="Extra tasks or note" value="'+esc(cur?cur.note:'')+'">'+
      '<div class="btns"><button class="btn pri small" data-act="save-clean">Save</button><button class="btn small" data-act="cancel">Cancel</button>'+
      (cur&&cur.cleaner?'<button class="btn small danger" data-act="unassign" data-date="'+d+'" data-unit="'+u+'">Unassign</button>':'')+'</div></div>';
  }
  function fp(p){
    var m=String(p||'').match(/^\s*(\d+)\s*A?\s*(?:\+\s*(\d+)\s*C?)?\s*$/i);
    if(!m) return String(p||'');
    return (m[2]&&m[2]!=='0')?m[1]+'+'+m[2]:m[1];
  }
  /* cleanLine: bold green name or NA bold red; shows edit UI when active */
  function cleanLine(u,d){
    var editingClean=S.edit&&S.edit.type==='clean'&&S.edit.date===d&&S.edit.unit===u;
    if(editingClean) return cleanEditor(u,d,assigned(u,d)[0]);
    var cl=assigned(u,d);
    if(cl.length) return '<button class="g-clean ok" data-act="edit-clean" data-date="'+d+'" data-unit="'+u+'">'+(cl[0].note?'<b style="color:var(--ok)">'+esc(cl[0].cleaner)+'</b> <small style="color:var(--muted)">'+esc(cl[0].note)+'</small>':'<b style="color:var(--ok)">'+esc(cl[0].cleaner)+'</b>')+'</button>';
    return '<button class="g-clean gap" data-act="edit-clean" data-date="'+d+'" data-unit="'+u+'"><b style="color:var(--bad)">NA</b></button>';
  }
  function nights(s){return Math.max(0,Math.round((new Date(s.out+'T00:00:00Z')-new Date(s.in+'T00:00:00Z'))/864e5))}
  function shortD(iso){return new Date(iso+'T00:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'UTC'})}
  /* stayBlock: line 1 = name+party; line 2 = arrival info (nothing if in house, time in orange if registered, NR bold orange if not) */
  function stayBlock(u,s,t0){
    var h='<div class="g-name">'+esc(s.guest)+' <span class="g-sub">'+esc(fp(s.party))+'</span></div>';
    if(s.in>=t0){
      if(S.edit&&S.edit.type==='arr'&&S.edit.id===s._id){
        h+='<div class="g-row"><div class="cedit" data-form="arr" data-id="'+esc(s._id)+'"><input type="text" data-f="arr" placeholder="e.g. 15:00" value="'+esc(s.arr||'')+'"><div class="btns"><button class="btn pri small" data-act="save-arr">Save</button><button class="btn small" data-act="cancel">Cancel</button></div></div></div>';
      } else if(s.reg==='ok'){
        h+='<div class="g-row"><button class="g-arr" style="color:var(--warn)" data-act="edit-arr" data-id="'+esc(s._id)+'">'+(s.arr||'–')+'</button></div>';
      } else {
        h+='<div class="g-row"><button class="g-arr" style="color:var(--warn);font-weight:700" data-act="edit-arr" data-id="'+esc(s._id)+'">NR</button></div>';
      }
    }
    return h;
  }
  function renderGrid(){
    var t0=todayJST(), units=['101','201','301'], days=[];
    for(var i=0;i<60;i++) days.push(addDays(t0,i));
    if(!S.stays.length) return '<div class="empty">'+(S.loaded.stays?'No bookings loaded yet. Ask Claude to refresh the board.':'Loading bookings')+'</div>';
    function cls(d,i){var w=dow(d);return (i===0?' td':(w===0||w===6?' we':''))}
    var h='<div class="scroller"><table class="cal"><thead><tr><th class="dcol">Unit</th>'+days.map(function(d,i){return '<th class="dt'+cls(d,i)+'">'+esc(fmt(d))+(i===0?' &middot; today':'')+'</th>'}).join('')+'</tr></thead><tbody>';
    units.forEach(function(u){
      var ss=staysFor(u).slice().sort(function(a,b){return a.in<b.in?-1:1});
      function occ(d){return ss.filter(function(s){return s.in<=d&&(d<s.out||(s.in===s.out&&d===s.in))})[0]}
      h+='<tr><td class="dcol">'+u+'</td>';
      var i=0;
      while(i<days.length){
        var d=days[i], s=occ(d);
        if(s){
          var span=1; while(i+span<days.length&&occ(days[i+span])===s) span++;
          var blk=stayBlock(u,s,t0);
          /* same-day turnover: a guest checks out on the arrival day of this block → cleaner is line 3 */
          var co=ss.filter(function(x){return x.out===d&&x!==s});
          if(co.length) blk+=cleanLine(u,d);
          h+='<td class="dt sb'+(s.in<days[0]?' cont':'')+(s.checkedIn?' checkedin':'')+'" colspan="'+span+'">'+blk+'</td>';
          i+=span;
        } else {
          /* empty cell: show clean bottom-aligned if a guest checked out today */
          var co2=ss.filter(function(x){return x.out===d});
          var c=co2.length?'<div style="margin-top:auto">'+cleanLine(u,d)+'</div>':'';
          h+='<td class="dt'+cls(d,i)+'" style="'+(c?'display:flex;flex-direction:column;min-height:56px':'')+'">'+c+'</td>';
          i++;
        }
      }
      h+='</tr>';
    });
    return h+'</tbody></table></div>';
  }

  /* ---------- Waiting and flags ---------- */
  function renderWait(){
    var b=S.board||{}, waiting=b.waiting||[], flags=(b.flags||[]).map(function(f){return typeof f==='string'?{sev:'warn',text:f}:f});
    var h='<section><h2>Waiting on others</h2>';
    h+=waiting.length?'<ul class="list">'+waiting.map(function(w,i){return '<li class="item"><div><b>'+esc(w.who)+'</b><div>'+esc(w.what)+'</div></div><button class="x" data-act="rm-wait" data-i="'+i+'" aria-label="Remove">&times;</button></li>'}).join('')+'</ul>':'<div class="empty">Nothing waiting.</div>';
    h+='<div class="addrow" data-form="wait"><input type="text" data-f="who" placeholder="Who"><input type="text" data-f="what" placeholder="What are you waiting for"><button class="btn pri" data-act="add-wait" style="grid-column:1/-1">Add</button></div>';
    h+='</section><section><h2>Flags</h2>';
    var all=flags.map(function(f,i){return {g:f,i:i}});
    h+=all.length?'<ul class="list">'+all.map(function(x){return '<li class="item '+(x.g.sev==='bad'?'bad':'warn')+'"><div>'+esc(x.g.text)+'</div><button class="x" data-act="rm-flag" data-i="'+x.i+'" aria-label="Remove">&times;</button></li>'}).join('')+'</ul>':'<div class="empty">No flags.</div>';
    h+='<div class="addrow" data-form="flag"><input type="text" data-f="text" placeholder="Add a flag or risk"><select data-f="sev"><option value="warn">Watch</option><option value="bad">Urgent</option></select><button class="btn pri" data-act="add-flag" style="grid-column:1/-1">Add</button></div>';
    return h+'</section>';
  }

  function renderNotes(){
    var t=(S.noteDirty&&S.noteDraft!=null)?S.noteDraft:((S.inbox&&S.inbox.text)||''), meta='';
    if(S.inbox&&S.inbox.savedAt) meta='Saved '+new Date(S.inbox.savedAt).toLocaleString('en-GB',{timeZone:'Asia/Tokyo',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})+(S.inbox.readAt&&S.inbox.readAt>=S.inbox.savedAt?', read by Claude':', not read by Claude yet');
    return '<div class="notes"><label class="lbl" for="inbox-text">Paste LINE messages or instructions for tomorrow morning\'s brief</label><textarea id="inbox-text">'+esc(t)+'</textarea>'+
      '<div class="btns"><button class="btn pri" data-act="save-notes">Save notes</button><span class="sub">'+esc(meta)+'</span></div></div>';
  }
  function renderPlaybook(){
    var pb=S.playbook; if(!pb||!pb.sections||!pb.sections.length) return '<div class="empty">The playbook has not been written yet.</div>';
    return '<p class="sub">How Claude works with you. '+esc(pb.updated||'')+'. Ask Claude to change it.</p>'+pb.sections.map(function(x,i){
      return '<details class="pb" data-pb="'+i+'"'+(S.pbOpen[i]?' open':'')+'><summary>'+esc(x.title)+'</summary><div class="pbtext">'+esc(x.text)+'</div></details>'}).join('');
  }

  function render(force){
    var ta=$('inbox-text'); if(ta&&S.noteDirty) S.noteDraft=ta.value;
    if(S.edit&&!force){S.stale=true;return}
    S.stale=false;
    $('view').innerHTML='<section class="blk" id="sec-cal"><h2 class="sec">Calendar</h2>'+renderGrid()+'</section>'+
      '<div class="lower"><section class="blk" id="sec-tasks"><h2 class="sec">Today</h2>'+renderToday()+'</section>'+
      '<section class="blk" id="sec-wait"><h2 class="sec">Waiting and flags</h2>'+renderWait()+'</section></div>'+
      '<div class="lower"><section class="blk" id="sec-notes"><h2 class="sec">Notes for Claude</h2>'+renderNotes()+'</section>'+
      '<section class="blk" id="sec-playbook"><h2 class="sec">Playbook</h2>'+renderPlaybook()+'</section></div>';
    var open=S.tasks.filter(function(t){return !t.done}).length;
    $('c-today').textContent=S.tasks.length?open:'';
    var n=((S.board&&S.board.flags)||[]).length+((S.board&&S.board.waiting)||[]).length;
    $('c-wait').textContent=(S.loaded.board||S.loaded.stays)?n:'';
  }

  /* ---------- Saving ---------- */
  function fval(root,f){var el=root.querySelector('[data-f="'+f+'"]');return el?el.value.trim():''}
  function setDone(id,val){
    var t=byId(S.tasks,id); if(!t) return; t.done=val; render(true);
